import json
import sys
def run(input: str) -> str:
    s = input.strip()
    if "Parse this" in s or "record:" in s:
        import re
        m = re.search(r"'([^']{10,})'", s)
        if m:
            s = m.group(1)
    if s.startswith("'") and s.endswith("'"):
        s = s[1:-1]
    elif s.startswith('"') and s.endswith('"'):
        s = s[1:-1]
    if " — fields are" in s:
        s = s.split(" — fields are")[0]
        s = s.strip()
    if s.startswith("'") and s.endswith("'"):
        s = s[1:-1]
    elif s.startswith('"') and s.endswith('"'):
        s = s[1:-1]
    s = s.strip()
    if len(s) < 5:
        return json.dumps({"error": "Record too short"})
    id = s[0:5].strip()
    import re
    m_bal = re.search(r'(\d{8})\s*$', s)
    if m_bal:
        bal_str = m_bal.group(1)
        bal_start = s.rfind(bal_str)
        name = s[5:bal_start].strip() if bal_start > 5 else s[5:14].strip()
    else:
        name = s[5:14].strip() if len(s) >= 14 else ""
        bal_part = s[14:].strip() if len(s) > 14 else ""
        bal_str = bal_part.split()[0] if bal_part else "0"
    try:
        cents = int(bal_str) if bal_str else 0
    except:
        cents = 0
    dollars = cents / 100
    return json.dumps({"id": id, "name": name, "balance": dollars})
if __name__ == '__main__':
    import sys, os
    data = sys.stdin.read()
    if not data:
        data = sys.argv[1] if len(sys.argv) > 1 else os.getenv('SANDBOX_INPUT', '')
    print(run(data))

