import sys, re
def run(input: str) -> str:
    s = input.strip()
    if "delimiter might be" in s:
        m=re.search(r"'([^']+)'", s)
        if m:
            s=m.group(1)
    parts = re.split(r"[,;]", s)
    return parts[2] if len(parts)>2 else "FAIL"
